'use strict';
const $ = s => document.querySelector(s);
const paths = {
 home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9', wardrobe:'M5 3h14v18H5zM12 3v18M9 11v3m6-3v3', scan:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 7h10v10H7z', outfit:'m8 3 4 3 4-3 6 5-4 4v9H6v-9L2 8z', shop:'M5 8h14l2 13H3zM8 8V6a4 4 0 0 1 8 0v2', care:'M20 4C10 2 3 7 4 14c1 7 12 8 15 0 1-3 1-7 1-10ZM5 19l10-10', analytics:'M4 3v18h17M8 17v-5m5 5V8m5 9V4', camera:'M4 7h4l2-3h4l2 3h4v13H4zM15 13a3 3 0 1 1-6 0 3 3 0 0 1 6 0', plus:'M12 5v14M5 12h14', arrow:'M5 12h14m-5-5 5 5-5 5', check:'m5 12 4 4 10-10', water:'M12 3S5 11 5 15a7 7 0 0 0 14 0c0-4-7-12-7-12Z', sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0', repair:'m5 3 4 4-2 2-4-4c-2 5 1 8 5 7l9 9 4-4-9-9c1-4-2-7-7-5Z'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.wardrobe}"/></svg>`;}
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed = [
 {id:'cream',name:'Kemeja putih favorit',category:'Atasan',color:'Putih',material:'Katun',pos:'0% 0%',wears:8},
 {id:'rust',name:'Cardigan senja',category:'Luaran',color:'Oranye',material:'Rajut',pos:'50% 0%',wears:2},
 {id:'denim',name:'Jeans biru andalan',category:'Bawahan',color:'Biru',material:'Denim',pos:'100% 0%',wears:12},
 {id:'beige',name:'Celana beige',category:'Bawahan',color:'Beige',material:'Katun',pos:'0% 100%',wears:5},
 {id:'olive',name:'Kaos olive',category:'Atasan',color:'Hijau',material:'Katun',pos:'50% 100%',wears:3},
 {id:'navy',name:'Overshirt navy',category:'Luaran',color:'Biru',material:'Katun',pos:'100% 100%',wears:1}
];
const KEY='sanda-demo-v1';
const initial=()=>({items:structuredClone(seed),logs:[],challengeStart:null});
let state=initial(),storageWarning=false;
try{const raw=localStorage.getItem(KEY);if(raw){const d=JSON.parse(raw);if(Array.isArray(d.items)&&d.items.every(i=>typeof i.id==='string'&&typeof i.name==='string'&&Number.isFinite(i.wears))&&Array.isArray(d.logs))state=d;}}catch{storageWarning=true;}
let current='home',filter='Semua',query='',scanDraft=null,outfit=null,outfitIndex=0,scanToken=0;
const pages=[['home','Beranda','home'],['wardrobe','Lemari saya','wardrobe'],['outfit','Outfit','outfit'],['shop','Cek belanja','shop'],['care','Perawatan','care'],['analytics','Aktivitas','analytics']];
const mobilePages=[['home','Beranda','home'],['wardrobe','Lemari','wardrobe'],['scan','Scan','scan'],['outfit','Outfit','outfit']];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageWarning=true;toast('Penyimpanan penuh/tidak tersedia. Perubahan hanya bertahan di sesi ini.');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function art(item,extra=''){const safeImage=typeof item.image==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(item.image);return `<span role="img" aria-label="${esc(item.name)}" class="garment-art ${safeImage?'uploaded':''} ${extra}" style="${safeImage?`background-image:url('${item.image}')`:`--pos:${esc(item.pos||'0% 0%')}`}"></span>`;}
function card(i){return `<button class="garment" data-action="detail" data-id="${esc(i.id)}">${art(i)}<span class="pill">${i.wears===0?'Baru ditambahkan':i.wears<=2?'Saatnya dipakai lagi':`${i.wears}× dipakai`}</span><div class="garment-info"><strong>${esc(i.name)}</strong><small>${esc(i.category)} · ${esc(i.color)}</small></div></button>`;}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
const scanButton=()=>`<a class="primary" href="#scan">${icon('plus')} Scan pakaian</a>`;
function navigate(page){if(location.hash===`#${page}`)render();else location.hash=page;}
function render(){current=location.hash.slice(1)||'home';if(![...pages.map(p=>p[0]),'scan'].includes(current))current='home';$('#nav').innerHTML=pages.map(([id,name,ic])=>`<a href="#${id}" class="${current===id?'active':''}" ${current===id?'aria-current="page"':''}>${icon(ic)}<span>${name}</span></a>`).join('');$('#mobile-nav').innerHTML=mobilePages.map(([id,name,ic])=>`<a href="#${id}" class="${current===id?'active':''} ${id==='scan'?'scan-tab':''}" ${current===id?'aria-current="page"':''}>${icon(ic)}<span>${name}</span></a>`).join('')+`<button data-action="more" class="${['shop','care','analytics'].includes(current)?'active':''}" aria-label="Menu lainnya" aria-haspopup="dialog">${icon('plus')}<span>Lainnya</span></button>`;$('#breadcrumb').textContent=`Lemari digital / ${pages.find(p=>p[0]===current)?.[1]||'Scan pakaian'}`;const views={home,wardrobe,scan:scanView,outfit:outfitView,shop:shopView,care:careView,analytics};$('#main').innerHTML=views[current]();window.scrollTo(0,0);}
function journey(){const done=[state.logs.some(l=>l.type==='add'),state.logs.some(l=>l.type==='wear'),state.logs.some(l=>l.type==='compare'),state.logs.some(l=>l.type==='plan')];const steps=[['scan','Masukkan pakaian','Foto dan konfirmasi detail'],['outfit','Pakai & catat','Susun outfit dari lemari'],['shop','Cek sebelum beli','Bandingkan pakaian incaran'],['care','Rawat atau teruskan','Repair, upcycle, atau donasi']];const next=done.findIndex(v=>!v);return `<section class="journey" aria-labelledby="journey-title"><div class="section-heading"><div><span class="small-label">ALUR UTAMA SANDA</span><h2 id="journey-title">Dari lemari, kembali ke lemari.</h2><p>Ikuti empat langkah ini saat mencoba prototipe.</p></div><span class="journey-count">${done.filter(Boolean).length} / 4 dicoba</span></div><div class="journey-grid">${steps.map(([route,title,desc],i)=>`<a href="#${route}" class="journey-step ${done[i]?'done':i===next?'next':''}"><span class="journey-number">${done[i]?icon('check'):i+1}</span><strong>${title}</strong><small>${desc}</small><span class="journey-status">${done[i]?'Sudah dicoba':i===next?'Langkah berikutnya':'Jelajahi'}</span></a>`).join('')}</div><p class="journey-foot">Setelah itu, lihat seluruh jejak percobaanmu di <a href="#analytics">Aktivitas ${icon('arrow')}</a></p></section>`;}
function home(){const low=[...state.items].sort((a,b)=>a.wears-b.wears).slice(0,3);return heading('Ada cerita di setiap pakaian.','Temukan lagi kemungkinan di dalam lemarimu.',scanButton())+`<section class="hero"><div class="hero-copy"><span class="small-label">Mulai dari yang kamu punya</span><h2>Lemari penuh.<br>Outfit selalu baru.</h2><p>Kenali pakaianmu, temukan padu padannya, dan pakai lebih lama bersama SANDA.</p><a href="#outfit" class="primary">Temukan outfit hari ini ${icon('arrow')}</a></div><div class="hero-mark"><img src="assets/sanda-mark-3d.png" alt="Logo 3D SANDA"><span class="hero-mark-caption">Satu pakaian, banyak kesempatan.</span></div></section>
 ${journey()}<div class="metrics"><div class="metric"><span class="metric-icon">${icon('wardrobe')}</span><div><strong>${state.items.length}</strong><small>Pakaian di lemarimu</small></div></div><div class="metric"><span class="metric-icon">${icon('outfit')}</span><div><strong>${state.logs.filter(l=>l.type==='wear').length}</strong><small>Pemakaian tercatat di demo</small></div></div><div class="metric"><span class="metric-icon">${icon('care')}</span><div><strong>${state.items.filter(i=>i.wears<=2).length}</strong><small>Item yang bisa dipakai lagi</small></div></div></div>
 <div class="home-bottom"><section><div class="section-heading"><div><h2>Kenalan lagi dengan favoritmu</h2><p>Pakaian yang paling jarang dipakai di koleksimu.</p></div><a class="text-button" href="#wardrobe">Lihat semua</a></div><div class="garments">${low.length?low.map(card).join(''):'<p>Scan pakaian pertama untuk memulai.</p>'}</div></section><aside class="insight"><span class="insight-symbol">↻</span><h3>Sebelum beli,<br>cek lemari dulu.</h3><p>Cari tahu apakah pakaian incaranmu punya pasangan di lemari.</p><a class="secondary" href="#shop">Cek pakaian incaran</a></aside></div>${storageWarning?'<p class="error">Penyimpanan browser terbatas; data mungkin hanya bertahan selama sesi ini.</p>':''}`;}
function wardrobe(){return heading('Lemari saya','Koleksi kecil, kemungkinan besar. Pilih pakaian untuk melihat detailnya.',scanButton())+`<div class="toolbar"><div class="filters">${['Semua','Atasan','Bawahan','Luaran'].map(c=>`<button class="chip ${filter===c?'active':''}" data-action="filter" data-value="${c}" aria-pressed="${filter===c}">${c}</button>`).join('')}</div><input class="search" id="search" type="search" placeholder="Cari pakaianmu…" aria-label="Cari pakaian" value="${esc(query)}"></div><p class="fine">Koleksi awal berisi data contoh. Foto yang kamu tambahkan hanya disimpan di browser ini.</p><div class="garments wardrobe-grid" id="wardrobe-results">${filteredCards()}</div>`;}
function filteredCards(){const a=state.items.filter(i=>(filter==='Semua'||i.category===filter)&&i.name.toLowerCase().includes(query.toLowerCase()));return a.length?a.map(card).join(''):'<div class="empty"><h2>Belum ada pakaian di sini</h2><p>Coba kata lain atau tambahkan foto pakaianmu.</p><a href="#scan" class="primary">Scan pakaian pertama</a></div>';}
function scanView(){scanDraft=null;return heading('Bawa lemarimu ke SANDA.','Mulai dengan satu pakaian. Kamu bisa menambah yang lain kapan saja.')+`<ol class="steps"><li class="active">1. Tambah foto</li><li>2. Konfirmasi detail</li><li>3. Simpan ke lemari</li></ol><div class="scan-layout"><section class="panel"><div class="dropzone" id="dropzone">${icon('camera')}<h3>Foto satu pakaian</h3><p>Tarik foto ke sini atau pilih dari perangkatmu.<br>JPG, PNG, atau WebP • maksimal 8 MB</p><div class="upload-actions"><button class="primary" data-action="upload">Pilih foto</button><button class="secondary" data-action="camera">Ambil foto</button></div><input id="file" type="file" accept="image/jpeg,image/png,image/webp" hidden><input id="camera-file" type="file" accept="image/*" capture="environment" hidden></div><p class="error" id="scan-error" role="alert"></p><h3>Atau coba dengan pakaian contoh</h3><div class="demo-options">${seed.slice(0,3).map(i=>`<button data-action="sample" data-id="${i.id}">${art(i)}<span>${i.category}</span></button>`).join('')}</div></section><aside class="panel"><h2>Foto yang mudah dikenali</h2><ol class="tips"><li>Letakkan satu pakaian di permukaan polos.</li><li>Pastikan seluruh bentuk pakaian terlihat.</li><li>Gunakan pencahayaan yang cukup.</li><li>Periksa kembali detail sebelum menyimpan.</li></ol><div class="notice"><strong>Mode prototipe</strong><br>Unggah foto berfungsi. Kategori dan warna dikonfirmasi manual; komposisi serat disalin dari label pakaian, bukan ditebak dari foto.</div><p class="fine">Tidak ada foto yang dikirim ke server. Pada HP, tombol ambil foto mengikuti dukungan kamera browser.</p></aside></div>`;}
async function acceptFile(file){if(!file)return;const error=$('#scan-error');if(!/^image\/(jpeg|png|webp)$/.test(file.type)){if(error)error.textContent='Format belum didukung. Pilih foto JPG, PNG, atau WebP.';return;}if(file.size>8*1024*1024){if(error)error.textContent='Foto terlalu besar. Pilih foto di bawah 8 MB.';return;}const token=++scanToken;try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=data;});if(current!=='scan'||token!==scanToken)return;const canvas=document.createElement('canvas');const scale=Math.min(1,800/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#f4f1ec';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);scanDraft={name:'Pakaian baru',category:'Atasan',color:'Putih',material:'Belum tahu',image:canvas.toDataURL('image/jpeg',.78),wears:0};reviewScan(false);}catch{if($('#scan-error'))$('#scan-error').textContent='Foto tidak bisa dibuka. Coba foto lain.';}}
function reviewScan(sample){$('#main').innerHTML=heading('Kenali pakaianmu.','Periksa detailnya sebelum masuk ke lemari digital.')+`<ol class="steps"><li>1. Tambah foto</li><li class="active">2. Konfirmasi detail</li><li>3. Simpan ke lemari</li></ol><div class="scan-layout"><div class="panel"><div class="preview-art">${art(scanDraft)}</div><div class="actions"><button class="secondary" data-action="rescan">Ganti foto</button></div></div><form id="scan-form" class="panel"><div class="notice">${sample?'Ini contoh simulasi scan. Foto dan detail contoh dapat kamu ubah.':'Foto berhasil dimuat. Kategori dan warna adalah isian awal, bukan hasil pengenalan AI.'}</div><label class="field">Nama pakaian<input name="name" value="${esc(scanDraft.name)}" required maxlength="60"></label><div class="form-grid"><label class="field">Kategori<select name="category">${opts(['Atasan','Bawahan','Luaran'],scanDraft.category)}</select></label><label class="field">Warna<select name="color">${opts(['Putih','Beige','Hitam','Biru','Oranye','Hijau','Merah','Abu-abu','Lainnya'],scanDraft.color)}</select></label></div><div class="label-field"><label class="field">Komposisi pada label pakaian<input name="labelText" placeholder="Contoh: 80% Katun, 20% Poliester" value="${esc(scanDraft.labelText||'')}" maxlength="160" autocomplete="off"></label><p class="fine">Salin komposisi dari label fisik. Boleh dikosongkan jika label belum ditemukan. Foto pakaian tidak dapat memastikan jenis seratnya.</p><p class="error" id="label-error" role="alert"></p></div><button class="primary" type="submit">${icon('check')} Simpan ke lemari</button></form></div>`;}
function opts(a,value){return a.map(s=>`<option ${s===value?'selected':''}>${esc(s)}</option>`).join('');}
function labelError(result){return result.reason==='total'?`Persentase berjumlah ${result.total}%. Periksa lagi agar totalnya 100%.`:result.reason==='unknown'?`${result.word} tidak dikenali sebagai serat. Denim dan rajut adalah jenis kain/struktur; cari nama serat pada label, misalnya katun atau poliester.`:result.reason==='percent'?'Persentase serat harus lebih dari 0% dan tidak lebih dari 100%.':'Gunakan format seperti 80% Katun, 20% Poliester.';}
function saveScan(form){const data=new FormData(form);const name=data.get('name').trim();if(!name){form.elements.name.setCustomValidity('Isi nama pakaian.');form.elements.name.reportValidity();return;}const labelText=String(data.get('labelText')||'').trim();const parsed=labelText?SandaMaterial.parseComposition(labelText):null;if(parsed&&!parsed.ok){$('#label-error').textContent=labelError(parsed);form.elements.labelText.focus();return;}const item={...scanDraft,id:crypto.randomUUID?crypto.randomUUID():`item-${Date.now()}`,name,category:data.get('category'),color:data.get('color'),material:parsed?parsed.primary:'Belum tahu',labelText,composition:parsed?parsed.composition:[],materialStatus:parsed?'label-entered':'unknown',wears:0};state.items.push(item);state.logs.unshift({type:'add',name:item.name,time:Date.now()});persist();$('#main').innerHTML=`<section class="success panel"><div class="success-mark">${icon('check')}</div><h1>Satu pakaian, peluang baru.</h1><p><strong>${esc(item.name)}</strong> sudah masuk ke lemari digitalmu.</p><div class="preview-art">${art(item)}</div><p class="muted">Sekarang cari padu padan dari pakaian yang kamu punya.</p><div class="actions"><a href="#outfit" class="primary">Temukan outfit</a><a href="#wardrobe" class="secondary">Lihat lemari saya</a><button data-action="rescan" class="text-button">Tambah pakaian lagi</button></div></section>`;scanDraft=null;}
function outfitView(){outfit=null;return heading('Pakai yang ada. Tampil berbeda.','Pilih kegiatanmu, lalu temukan kombinasi dari lemari sendiri.')+`<div class="outfit-layout"><form class="panel" id="outfit-form"><h2>Rencanamu hari ini?</h2><br><label class="field">Kegiatan<select name="occasion"><option>Kuliah</option><option>Kerja</option><option>Hangout</option></select></label><label class="field">Suasana yang kamu mau<select name="style"><option>Santai</option><option>Rapi</option></select></label><label class="field">Cuaca yang kamu rasakan<select name="weather"><option>Hangat</option><option>Sejuk</option></select></label><button class="primary" type="submit">${icon('outfit')} Susun outfit</button><p class="fine" style="margin-top:16px">Demo menggunakan aturan kategori, kegiatan, dan frekuensi pemakaian. Belum memakai AI atau cuaca langsung.</p></form><section class="outfit-result" id="outfit-result"><div class="empty"><span class="insight-symbol">${icon('outfit')}</span><h2>Outfit berikutnya ada di lemarimu.</h2><p>Kami prioritaskan pakaian yang jarang kamu pakai.</p></div><div class="outfit-board">${state.items.slice(0,2).map(i=>`<div>${art(i)}<p class="fine">${esc(i.name)}</p></div>`).join('')}</div></section></div>`;}
function makeOutfit(form){const values=Object.fromEntries(new FormData(form));const order=items=>items.sort((a,b)=>a.wears-b.wears);const tops=order(state.items.filter(i=>i.category==='Atasan'));const bottoms=order(state.items.filter(i=>i.category==='Bawahan'));if(!tops.length||!bottoms.length){$('#outfit-result').innerHTML='<div class="empty"><h2>Koleksinya belum lengkap.</h2><p>Tambahkan minimal satu atasan dan satu bawahan untuk menyusun outfit.</p><a class="primary" href="#scan">Tambah pakaian</a></div>';return;}const formal=values.style==='Rapi'||values.occasion==='Kerja';const ranked=formal?[...tops].sort((a,b)=>(/kemeja/i.test(b.name)?1:0)-(/kemeja/i.test(a.name)?1:0)):tops;const lower=formal?[...bottoms].sort((a,b)=>(/celana/i.test(b.name)?1:0)-(/celana/i.test(a.name)?1:0)):bottoms;const picked=[ranked[outfitIndex%ranked.length],lower[Math.floor(outfitIndex/ranked.length)%lower.length]];if(values.weather==='Sejuk'){const jacket=order(state.items.filter(i=>i.category==='Luaran'))[0];if(jacket)picked.push(jacket);}outfit={items:picked,values,logged:false};$('#outfit-result').innerHTML=`<div class="section-heading"><div><span class="tag">Dari lemarimu sendiri</span><h2 style="margin-top:12px">Siap untuk ${esc(values.occasion.toLowerCase())}.</h2></div><button class="text-button" data-action="shuffle">Coba kombinasi lain</button></div><div class="outfit-board">${picked.map(i=>`<div>${art(i)}<strong>${esc(i.name)}</strong><p class="fine">${i.wears}× dipakai</p></div>`).join('')}</div><p class="result-explanation">${formal?'Pilihan lebih rapi untuk kegiatanmu.':'Padu padan santai dari koleksi yang sudah ada.'} ${values.weather==='Sejuk'?'Luaran ditambahkan jika tersedia untuk cuaca sejuk.':'Tanpa tambahan luaran untuk cuaca hangat.'} Tidak perlu membeli pakaian baru.</p><button class="primary" data-action="wear-outfit">${icon('check')} Pakai outfit ini hari ini</button>`;}
function localDay(t=Date.now()){const d=new Date(t);return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;}
function recordWear(items){const today=localDay();const fresh=items.filter(i=>!state.logs.some(l=>l.type==='wear'&&l.itemId===i.id&&localDay(l.time)===today));if(!fresh.length){toast('Pemakaian pakaian ini sudah dicatat hari ini.');return false;}fresh.forEach(i=>{i.wears++;state.logs.unshift({type:'wear',itemId:i.id,name:i.name,time:Date.now()});});persist();toast(`${fresh.length} pakaian dicatat dipakai hari ini.`);return true;}
function shopView(){return heading('Sebelum beli, kenali kebutuhannya.','Bandingkan pakaian incaran dengan isi lemari digitalmu.')+`<div class="scan-layout"><form id="shop-form" class="panel"><h2>Pakaian yang sedang kamu incar</h2><br><label class="field">Nama pakaian<input name="name" placeholder="Contoh: cardigan oranye" required maxlength="60"></label><div class="form-grid"><label class="field">Kategori<select name="category">${opts(['Atasan','Bawahan','Luaran'],'Luaran')}</select></label><label class="field">Warna<select name="color">${opts(['Putih','Beige','Hitam','Biru','Oranye','Hijau','Merah','Abu-abu','Lainnya'],'Oranye')}</select></label></div><button class="primary" type="submit">${icon('shop')} Bandingkan dengan lemari</button><p class="fine" style="margin-top:16px">Perbandingan demo berdasarkan kategori dan warna yang kamu pilih. Belum membaca tautan marketplace.</p></form><section class="panel" id="shop-result"><span class="insight-symbol">↻</span><h2>Belanja dengan lebih yakin.</h2><ol class="tips"><li>Periksa apakah kamu sudah punya yang serupa.</li><li>Temukan pasangan dari koleksi saat ini.</li><li>Pertimbangkan kembali kebutuhan sebelum membeli.</li></ol></section></div>`;}
function compare(form){const v=Object.fromEntries(new FormData(form));const similar=state.items.filter(i=>i.category===v.category&&i.color===v.color);const partners=state.items.filter(i=>v.category==='Bawahan'?i.category==='Atasan':i.category==='Bawahan');state.logs.unshift({type:'compare',name:v.name.trim(),similar:similar.length,time:Date.now()});persist();$('#shop-result').innerHTML=`<span class="tag">Hasil cek lemari</span><h2 style="margin:14px 0">${similar.length?'Ada yang mirip di lemarimu.':partners.length?'Ada pasangan di lemarimu.':'Lengkapi data lemari dahulu.'}</h2><p class="muted">Untuk ${esc(v.name.trim()||'pakaian incaranmu')}, kami menemukan:</p><ul class="compare-list"><li><strong>${similar.length} pakaian</strong> dengan kategori dan warna yang sama.</li><li><strong>${partners.length} calon pasangan</strong> dari kategori pelengkap. Kecocokan gaya tetap perlu kamu nilai.</li></ul>${similar.length?`<div class="outfit-board">${similar.slice(0,2).map(i=>`<div>${art(i)}<p class="fine">${esc(i.name)}</p></div>`).join('')}</div><p>Coba pakai koleksi yang serupa terlebih dahulu sebelum membeli lagi.</p>`:'<p>Pertimbangkan kebutuhan, kenyamanan, dan seberapa sering akan dipakai.</p>'}<div class="next-step"><strong>Langkah berikutnya</strong><p>Rawat pakaian yang sudah ada agar bisa terus dipakai. Jika sudah jarang digunakan, pilih repair, upcycle, atau donasi.</p><div class="actions"><a class="primary" href="#care">Lihat perawatan ${icon('arrow')}</a><a class="secondary" href="#outfit">Coba padu padan</a></div></div>`;}
function careView(){const first=state.items[0];return heading('Rawat baik-baik. Pakai lebih lama.','Kenali labelnya, lalu pilih langkah yang sesuai untuk pakaianmu.')+`<section class="care-lead"><div class="care-lead-copy"><span class="small-label">Perawatan SANDA</span><h2>Satu pakaian bisa ikut banyak cerita.</h2><p>Mulai dari membaca label, lalu rawat dengan cara yang tepat agar tetap nyaman dipakai.</p></div><img class="care-photo" src="assets/care-wash.png" alt="Tangan mencuci kemeja dengan lembut" loading="eager"></section><div class="care-picker panel"><label class="field">Pilih pakaian<select id="care-select">${state.items.map(i=>`<option value="${esc(i.id)}">${esc(i.name)}</option>`).join('')}</select></label><p class="fine">Pilih satu pakaian untuk melihat catatan bahan dan langkah berikutnya.</p></div><div id="care-content">${careContent(first)}</div>`;}
function careContent(item){if(!item)return '<div class="empty"><h2>Belum ada pakaian untuk dirawat.</h2><p>Tambahkan satu pakaian dan isi labelnya agar panduannya lebih relevan.</p><a class="primary" href="#scan">Tambah pakaian</a></div>';const parts=Array.isArray(item.composition)?item.composition:[];const known=parts.length>0;const summary=known?parts.map(p=>`${esc(p.fiber)} ${p.percent}%`).join(' · '):'Komposisi belum dicatat';const older=item.material&&item.material!=='Belum tahu'?`Data contoh sebelumnya: ${esc(item.material)}. ${['Denim','Rajut'].includes(item.material)?'Ini jenis kain atau struktur, bukan nama serat.':''}`:'Foto pakaian tidak menunjukkan komposisi serat secara pasti.';return `<section class="care-material panel"><div><span class="small-label">Pakaian pilihanmu</span><h2>${esc(item.name)}</h2><p class="material-summary">${summary}</p><p class="material-status">${known?'Berdasarkan label yang kamu isi':'Belum berdasarkan label pakaian'}</p><p class="fine">${known?'Komposisi dicatat dari teks yang kamu masukkan. SANDA belum memverifikasi label melalui kamera.':older}</p></div><form id="care-label-form" data-id="${esc(item.id)}"><label class="field">Komposisi pada label pakaian<input name="labelText" value="${esc(item.labelText||'')}" placeholder="Contoh: 80% Katun, 20% Poliester" maxlength="160" autocomplete="off" required></label><p class="fine">Salin persentase serat dari label fisik. Total harus 100%. Denim dan rajut bukan nama serat.</p><p class="error" id="label-error" role="alert"></p><button class="secondary" type="submit">Simpan komposisi</button></form></section><div class="care-guidance"><div class="care-guidance-head"><span class="small-label">Untuk ${esc(item.name)}</span><h2>Mulai dari label, bukan tebakan.</h2><p>Komposisi membantu mengenali kain. Simbol dan instruksi perawatan pada label tetap menentukan cara cuci, kering, serta setrika yang aman.</p></div><div class="care-guidance-list"><div><strong>01 · Saat mencuci</strong><p>Periksa apakah label mengizinkan cuci tangan atau mesin dan ikuti suhu yang tertera. Pisahkan warna jika perlu.</p></div><div><strong>02 · Saat mengeringkan</strong><p>Ikuti simbol pengeringan. Untuk pakaian rajut, ratakan di permukaan datar bila label menyarankannya.</p></div><div><strong>03 · Saat menyimpan</strong><p>Pastikan pakaian benar-benar kering. Perbaiki kancing atau jahitan kecil sebelum kerusakannya meluas.</p></div></div></div><div class="care-photo-grid"><figure><img class="care-photo" src="assets/care-dry.png" alt="Cardigan rajut dirapikan saat dikeringkan mendatar" loading="lazy"><figcaption><strong>Keringkan dengan perhatian.</strong><span>Ikuti simbol pada label agar bentuk kain tetap terjaga.</span></figcaption></figure><figure><img class="care-photo" src="assets/care-repair.png" alt="Tangan menjahit kembali kancing kemeja" loading="lazy"><figcaption><strong>Perbaikan kecil, masa pakai panjang.</strong><span>Kancing lepas bisa menjadi alasan untuk merawat, bukan membuang.</span></figcaption></figure></div><section class="care-next panel"><div><h2>Kalau jarang dipakai, masih ada pilihannya.</h2><p>Pilih satu rencana untuk ${esc(item.name)}. SANDA akan menyimpannya di Aktivitas.</p></div><div class="actions"><button class="secondary" data-action="circular" data-kind="repair" data-id="${esc(item.id)}">Rencanakan repair</button><button class="secondary" data-action="circular" data-kind="upcycle" data-id="${esc(item.id)}">Ide upcycle</button><button class="secondary" data-action="circular" data-kind="donasi" data-id="${esc(item.id)}">Siapkan donasi</button></div><p class="fine">Ini rencana pribadi, belum terhubung ke penjahit atau layanan donasi.</p></section>`;}
function saveCareLabel(form){const item=state.items.find(i=>i.id===form.dataset.id);if(!item)return;const labelText=String(new FormData(form).get('labelText')||'').trim();const parsed=SandaMaterial.parseComposition(labelText);if(!parsed.ok){$('#label-error').textContent=labelError(parsed);form.elements.labelText.focus();return;}item.labelText=labelText;item.composition=parsed.composition;item.material=parsed.primary;item.materialStatus='label-entered';persist();$('#care-content').innerHTML=careContent(item);toast('Komposisi tersimpan dari label yang kamu isi.');}
function analytics(){const wear=state.logs.filter(l=>l.type==='wear');const used=new Set(wear.map(l=>l.itemId)).size;const progress=state.items.length?Math.round(used/state.items.length*100):0;const days=state.challengeStart?new Set(wear.filter(l=>l.time>=state.challengeStart).map(l=>localDay(l.time))).size:0;return heading('Setiap pemakaian punya arti.','Lihat kebiasaanmu tumbuh, satu pakaian demi satu pakaian.')+`<div class="stat-list"><section class="panel"><h3>Pakaian dipakai selama demo</h3><strong>${used}<span class="muted" style="font-size:1rem"> / ${state.items.length} item</span></strong><div class="bar"><span style="width:${progress}%"></span></div><p class="fine">Dihitung dari pemakaian yang kamu catat, bukan angka riwayat contoh.</p></section><section class="panel"><h3>Tantangan pakai ulang 7 hari</h3><strong>${Math.min(days,7)}<span class="muted" style="font-size:1rem"> / 7 hari</span></strong><div class="bar"><span style="width:${Math.min(days/7*100,100)}%"></span></div>${state.challengeStart?`<p class="fine">${days>=7?'Tantangan selesai!':'Catat outfit di hari yang berbeda untuk melanjutkan.'}</p>`:'<button class="text-button" data-action="challenge">Mulai tantangan hari ini</button>'}</section></div><section class="panel" style="margin-top:24px"><h2>Aktivitas terbarumu</h2>${state.logs.length?state.logs.slice(0,20).map(l=>`<div class="activity"><span>${l.type==='wear'?'Dipakai':l.type==='add'?'Ditambahkan':l.type==='compare'?'Cek belanja':'Rencana '+esc(l.kind)}: <strong>${esc(l.name)}</strong></span><time>${new Date(l.time).toLocaleDateString('id-ID',{day:'numeric',month:'short'})}</time></div>`).join(''):'<div class="empty" style="margin-top:18px"><p>Belum ada aktivitas. Pilih outfit dan catat pemakaian pertamamu.</p><a class="primary" href="#outfit">Susun outfit</a></div>'}</section><p class="fine" style="margin-top:18px">Pengurangan emisi belum dihitung. Estimasi jejak karbon memerlukan data bahan, produksi, dan metode perhitungan yang tervalidasi.</p>`;}
function openModal(html){$('#modal-content').innerHTML=`<div class="dialog-body">${html}</div>`;$('#modal').showModal();}
function detail(id){const i=state.items.find(x=>x.id===id);if(!i)return;const material=Array.isArray(i.composition)&&i.composition.length?i.composition.map(p=>`${esc(p.fiber)} ${esc(p.percent)}%`).join(' · '):'Komposisi belum berdasarkan label';openModal(`<h2>${esc(i.name)}</h2>${art(i)}<p>${esc(i.category)} · ${esc(i.color)}</p><p>${material}</p><p><strong>${i.wears}× dipakai</strong>${seed.some(s=>s.id===id)?' (termasuk riwayat contoh)':''}</p><button class="primary" data-action="wear-item" data-id="${esc(id)}">Catat dipakai hari ini</button><div class="actions"><button class="secondary" data-action="care-item" data-id="${esc(id)}">Panduan perawatan</button><button class="text-button" data-action="delete-item" data-id="${esc(id)}">Hapus dari lemari</button></div>`);}
function guide(){openModal('<h2>Coba perjalanan SANDA</h2><p>Demo dimulai dengan 6 pakaian contoh. Kamu juga bisa menambahkan pakaianmu sendiri.</p><ol><li><strong>Scan pakaian:</strong> unggah foto atau gunakan contoh, isi komposisi dari label bila tersedia, lalu simpan.</li><li><strong>Outfit:</strong> pilih kegiatan dan cuaca, susun kombinasi, lalu catat pemakaian.</li><li><strong>Cek belanja:</strong> bandingkan kategori dan warna incaran dengan lemari.</li><li><strong>Perawatan:</strong> baca panduan, perbarui label, dan simpan rencana repair, upcycle, atau donasi.</li><li><strong>Aktivitas:</strong> lihat catatan penggunaan dan ikuti tantangan pakai ulang.</li></ol><div class="notice">Pengenalan foto dan OCR label belum tersedia. Rekomendasi menggunakan aturan sederhana. Data hanya tersimpan di browser perangkat ini.</div><button class="primary" data-action="start-scan">Mulai dengan scan pakaian</button>');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 if(a==='guide'){if($('#more-menu').open)$('#more-menu').close();guide();}
 if(a==='more')$('#more-menu').showModal();
 if(a==='close-more')$('#more-menu').close();
 if(a==='start-scan'){$('#modal').close();navigate('scan');}
 if(a==='upload')$('#file').click();if(a==='camera')$('#camera-file').click();
 if(a==='sample'){scanDraft={...seed.find(i=>i.id===id),wears:0};reviewScan(true);}
 if(a==='rescan'){$('#main').innerHTML=scanView();}
 if(a==='filter'){filter=b.dataset.value;$('#main').innerHTML=wardrobe();}
 if(a==='detail')detail(id);
 if(a==='shuffle'){outfitIndex++;makeOutfit($('#outfit-form'));}
 if(a==='wear-outfit'&&outfit){recordWear(outfit.items);b.textContent='Pemakaian hari ini tercatat';b.disabled=true;b.insertAdjacentHTML('afterend','<div class="next-step"><strong>Sudah tercatat. Apa berikutnya?</strong><p>Sebelum membeli yang baru, cek apakah pakaian incaranmu sudah ada atau mudah dipadukan dengan koleksimu.</p><a class="primary" href="#shop">Cek sebelum beli '+icon('arrow')+'</a></div>');}
 if(a==='wear-item'){const i=state.items.find(i=>i.id===id);if(i)recordWear([i]);$('#modal').close();render();}
 if(a==='care-item'){$('#modal').close();navigate('care');setTimeout(()=>{const select=$('#care-select');if(select){select.value=id;$('#care-content').innerHTML=careContent(state.items.find(i=>i.id===id));}},0);}
 if(a==='delete-item'){const i=state.items.find(i=>i.id===id);$('#modal-content').innerHTML=`<div class="dialog-body"><h2>Hapus ${esc(i.name)}?</h2><p>Foto dan pakaian ini akan dihapus dari lemari di browser ini.</p><div class="actions"><button class="primary" data-action="confirm-delete" data-id="${esc(id)}">Ya, hapus pakaian</button><button class="secondary" data-action="cancel">Batal</button></div></div>`;}
 if(a==='confirm-delete'){state.items=state.items.filter(i=>i.id!==id);state.logs=state.logs.filter(l=>l.itemId!==id);persist();$('#modal').close();render();toast('Pakaian dihapus dari lemari.');}
 if(a==='cancel')$('#modal').close();
 if(a==='circular'){const i=state.items.find(i=>i.id===id),kind=b.dataset.kind;const text={repair:'Periksa bagian yang rusak, foto detailnya, dan diskusikan opsi perbaikan dengan penjahit.',upcycle:'Pertimbangkan mengubah ukuran atau fungsi. Kain layak pakai bisa dijadikan aksesori atau kantong kecil.',donasi:'Pastikan pakaian bersih dan layak pakai. Cari penerima yang membutuhkan dan konfirmasi persyaratan donasi.'};openModal(`<h2>Rencana ${kind}</h2><p>Untuk <strong>${esc(i.name)}</strong>.</p><p>${text[kind]}</p><p class="fine">Menyimpan rencana tidak membuat pemesanan atau menghubungi mitra.</p><button class="primary" data-action="save-plan" data-id="${esc(id)}" data-kind="${kind}">Simpan rencana ${kind}</button>`);}
 if(a==='save-plan'){const i=state.items.find(i=>i.id===id);state.logs.unshift({type:'plan',itemId:id,name:i.name,kind:b.dataset.kind,time:Date.now()});persist();$('#modal').close();$('#care-content').insertAdjacentHTML('beforeend','<div class="next-step"><strong>Rencana tersimpan.</strong><p>Lihat catatan pemakaian, cek belanja, dan rencana pakaianmu dalam satu tempat.</p><a class="primary" href="#analytics">Lihat Aktivitas '+icon('arrow')+'</a></div>');toast('Rencana tersimpan di Aktivitas.');}
 if(a==='challenge'){state.challengeStart=Date.now();persist();render();toast('Tantangan dimulai. Catat pemakaian outfit pertamamu!');}
 if(a==='reset')openModal('<h2>Mulai ulang demo?</h2><p>Foto unggahan, aktivitas, dan rencana di browser ini akan dihapus. Enam pakaian contoh akan dipulihkan.</p><div class="actions"><button class="primary" data-action="confirm-reset">Atur ulang demo</button><button class="secondary" data-action="cancel">Batal</button></div>');
 if(a==='confirm-reset'){state=initial();filter='Semua';query='';persist();$('#modal').close();navigate('home');toast('Demo kembali ke kondisi awal.');}
});
document.addEventListener('submit',e=>{if(['scan-form','outfit-form','shop-form','care-label-form'].includes(e.target.id)){e.preventDefault();if(e.target.id==='scan-form')saveScan(e.target);if(e.target.id==='outfit-form'){outfitIndex=0;makeOutfit(e.target);}if(e.target.id==='shop-form')compare(e.target);if(e.target.id==='care-label-form')saveCareLabel(e.target);}});
document.addEventListener('change',e=>{if(['file','camera-file'].includes(e.target.id))acceptFile(e.target.files[0]);if(e.target.id==='care-select')$('#care-content').innerHTML=careContent(state.items.find(i=>i.id===e.target.value));});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#wardrobe-results').innerHTML=filteredCards();}if(e.target.name==='name')e.target.setCustomValidity('');if(e.target.name==='labelText'&&$('#label-error'))$('#label-error').textContent='';});
document.addEventListener('dragover',e=>{const drop=e.target.closest('#dropzone');if(drop){e.preventDefault();drop.classList.add('drag');}});
document.addEventListener('dragleave',e=>e.target.closest('#dropzone')?.classList.remove('drag'));
document.addEventListener('drop',e=>{const drop=e.target.closest('#dropzone');if(drop){e.preventDefault();drop.classList.remove('drag');acceptFile(e.dataTransfer.files[0]);}});
$('.close').addEventListener('click',()=>$('#modal').close());
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',()=>{if($('#more-menu').open)$('#more-menu').close();scanToken++;render();});render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_sanda_wardrobe',title:'Baca lemari SANDA',description:'Read the current device-local wardrobe without changing data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({items:state.items.map(({id,name,category,color,wears})=>({id,name,category,color,wears}))})})).catch(()=>{});}catch{}}
